import{_ as e,o as r,c as s,ai as t}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Node.js 面试 · 异步与并发","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodejs/async-interview.md","filePath":"guide/nodejs/async-interview.md"}'),i={name:"guide/nodejs/async-interview.md"};function d(n,a,o,l,c,h){return r(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="node-js-面试-·-异步与并发" tabindex="-1">Node.js 面试 · 异步与并发 <a class="header-anchor" href="#node-js-面试-·-异步与并发" aria-label="Permalink to “Node.js 面试 · 异步与并发”">​</a></h1><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>回调地狱怎么解决？</li><li>Promise 状态？<code>all</code> / <code>allSettled</code> / <code>race</code>？</li><li>async/await 错误怎么捕获？</li><li>如何控制并发（比如同时只 5 个请求）？</li><li>什么会堵住事件循环？怎么查？</li><li><code>worker_threads</code> 什么时候用？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-回调-→-promise-→-async-await" tabindex="-1">1）回调 → Promise → async/await <a class="header-anchor" href="#_1-回调-→-promise-→-async-await" aria-label="Permalink to “1）回调 → Promise → async/await”">​</a></h3><p>现代代码以 async/await 为主；底层仍是 Promise。<br> 库若只提供回调，可 <code>promisify</code> 包装。</p><h3 id="_2-组合子" tabindex="-1">2）组合子 <a class="header-anchor" href="#_2-组合子" aria-label="Permalink to “2）组合子”">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>含义</th></tr></thead><tbody><tr><td><code>Promise.all</code></td><td>全成功才成功；一个失败即失败</td></tr><tr><td><code>allSettled</code></td><td>等全部结束，看各自状态</td></tr><tr><td><code>race</code></td><td>谁先结束听谁（含失败）</td></tr><tr><td><code>any</code></td><td>谁先成功听谁</td></tr></tbody></table><p>批量任务要「部分失败也继续」→ <code>allSettled</code>。</p><h3 id="_3-错误处理" tabindex="-1">3）错误处理 <a class="header-anchor" href="#_3-错误处理" aria-label="Permalink to “3）错误处理”">​</a></h3><p><code>try/catch</code> 包 await；别忘了异步回调里的错误也要接。<br> Express 等要有统一错误中间件；Promise 链别留未处理 rejection。</p><h3 id="_4-并发控制" tabindex="-1">4）并发控制 <a class="header-anchor" href="#_4-并发控制" aria-label="Permalink to “4）并发控制”">​</a></h3><p>不能无脑 <code>all</code> 一千个请求。<br> 写法：池化（自己写队列 / <code>p-limit</code> 一类）；设备采集同样要<strong>限制并发连接数</strong>。</p><h3 id="_5-堵住事件循环" tabindex="-1">5）堵住事件循环 <a class="header-anchor" href="#_5-堵住事件循环" aria-label="Permalink to “5）堵住事件循环”">​</a></h3><p>症状：定时器不准、接口全卡、UI（若同进程）冻。<br> 原因：同步大循环、同步读大文件、<code>JSON.parse</code> 巨大字符串、加密算太久。<br> 处理：拆任务、<code>setImmediate</code> 让出、Worker、或把重活丢给 Java/Python 进程。</p><h3 id="_6-worker-threads" tabindex="-1">6）worker_threads <a class="header-anchor" href="#_6-worker-threads" aria-label="Permalink to “6）worker_threads”">​</a></h3><p>真要在 Node 里做 CPU 活，用 Worker 开线程跑；注意序列化开销。<br> Electron 里更常见：<strong>主进程小心别堵</strong>，重活丢子进程。</p><hr><h2 id="设备轮询场景-贴项目" tabindex="-1">设备轮询场景（贴项目） <a class="header-anchor" href="#设备轮询场景-贴项目" aria-label="Permalink to “设备轮询场景（贴项目）”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>定时采集 → 异步 IO</span></span>
<span class="line"><span>  → 超时/重连</span></span>
<span class="line"><span>  → 结果抛到队列</span></span>
<span class="line"><span>  → UI 只消费状态，不直接死循环读设备</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>金句：<strong>采集别堵渲染；失败要可见。</strong></p>`,23)])])}const m=e(i,[["render",d]]);export{b as __pageData,m as default};
